class Solution { public int maximumInvitations(int[] favorite){int n=favorite.length;int[] indegree=new int[n],depth=new int[n];Arrays.fill(depth,1);for(int value:favorite)indegree[value]++;Queue<Integer> queue=new ArrayDeque<>();for(int i=0;i<n;i++)if(indegree[i]==0)queue.offer(i);while(!queue.isEmpty()){int node=queue.poll(),next=favorite[node];depth[next]=Math.max(depth[next],depth[node]+1);if(--indegree[next]==0)queue.offer(next);}int pairSum=0,longestCycle=0;boolean[] seen=new boolean[n];for(int start=0;start<n;start++)if(indegree[start]>0&&!seen[start]){int length=0,node=start;do{seen[node]=true;length++;node=favorite[node];}while(node!=start);if(length==2)pairSum+=depth[start]+depth[favorite[start]];else longestCycle=Math.max(longestCycle,length);}return Math.max(pairSum,longestCycle);} }
